package raft

import (
    "encoding/json"
    "fmt"
    "testing"
)

func TestAssuranceCommitAccounting(t *testing.T) {
    config := func(ids ...ServerID) Configuration {
        result := Configuration{}
        for _, id := range ids {
            result.Servers = append(result.Servers, Server{ID: id, Suffrage: Voter})
        }
        return result
    }
    c := newCommitment(make(chan struct{}, 1), config("a", "b", "c"), 2)
    type sample struct {
        reports map[ServerID]uint64
        commit uint64
        start uint64
    }
    read := func() sample {
        c.Lock()
        defer c.Unlock()
        s := sample{reports: make(map[ServerID]uint64), commit: c.commitIndex, start: c.startIndex}
        for id, value := range c.matchIndexes {
            s.reports[id] = value
        }
        return s
    }
    emit := func(name string, before, after sample, ignored bool) {
        _, a := after.reports["a"]
        _, b := after.reports["b"]
        _, d := after.reports["c"]
        state := map[string]interface{}{
            "object": "commitment-1", "event": name,
            "start": after.start, "commit": after.commit,
            "previousCommit": before.commit,
            "voterA": a, "voterB": b, "voterC": d,
            "reportA": after.reports["a"], "reportB": after.reports["b"], "reportC": after.reports["c"],
            "previousA": before.reports["a"], "previousB": before.reports["b"], "previousC": before.reports["c"],
            "ignored": ignored,
        }
        data, err := json.Marshal(map[string]interface{}{"event": name, "state": state})
        if err != nil { t.Fatal(err) }
        fmt.Println("CA_EVENT " + string(data))
    }
    check := func(before, after sample, ignored bool) {
        if after.commit < before.commit {
            t.Errorf("commit decreased: %d to %d", before.commit, after.commit)
        }
        if after.commit > before.commit {
            support := 0
            for _, value := range after.reports {
                if value >= after.commit { support++ }
            }
            if after.commit < after.start || 2*support <= len(after.reports) {
                t.Errorf("unsupported advancement: previous=%d commit=%d start=%d support=%d voters=%d", before.commit, after.commit, after.start, support, len(after.reports))
            }
        }
        if ignored {
            same := before.commit == after.commit && len(before.reports) == len(after.reports)
            for id, value := range before.reports {
                next, present := after.reports[id]
                if !present || next != value { same = false }
            }
            if !same { t.Errorf("ignored report changed support or commitment") }
        }
    }
    initial := read()
    emit("initial", initial, initial, false)
    match := func(id ServerID, value uint64) {
        before := read()
        prior, present := before.reports[id]
        ignored := !present || value <= prior
        c.match(id, value)
        after := read()
        emit("match_completed", before, after, ignored)
        check(before, after, ignored)
    }
    replace := func(ids ...ServerID) {
        before := read()
        c.setConfiguration(config(ids...))
        after := read()
        emit("configuration_completed", before, after, false)
        check(before, after, false)
    }
    match("a", 1)
    match("b", 1)
    match("a", 2)
    match("b", 2)
    match("a", 1)
    replace("a", "b")
    match("c", 3)
    match("a", 3)
    match("b", 3)
    replace()
    match("a", 3)
    replace("a", "c")
    match("a", 2)
    match("c", 3)
    replace("a", "b", "c")
    match("b", 3)
}
